BEGIN;
CREATE TABLE IF NOT EXISTS forge_workflow_schema_versions (family text NOT NULL,version integer NOT NULL CHECK(version>0),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('DRAFT','ACTIVE','RETIRED')),definition jsonb NOT NULL DEFAULT '{}'::jsonb,contract jsonb NOT NULL,canonical_hash char(64) NOT NULL,migration_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),activated_at timestamptz,retired_at timestamptz,PRIMARY KEY(family,version),UNIQUE(family,canonical_hash));
CREATE INDEX IF NOT EXISTS forge_workflow_schema_versions_status_idx ON forge_workflow_schema_versions(family,status,version DESC);
CREATE TABLE IF NOT EXISTS forge_workflow_schema_migrations (id uuid PRIMARY KEY,family text NOT NULL,from_version integer NOT NULL CHECK(from_version>0),to_version integer NOT NULL CHECK(to_version>0),compatibility text NOT NULL CHECK(compatibility IN ('FORWARD','BACKWARD','FULL','NONE')),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,metadata_hash char(64),state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','VALIDATED','ROLLED_OUT','ROLLED_BACK','REJECTED')),dry_run boolean NOT NULL DEFAULT false,actor text NOT NULL,reason text NOT NULL DEFAULT '',validation_report jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),rolled_out_at timestamptz,rolled_back_at timestamptz,UNIQUE(family,from_version,to_version,metadata_hash));
CREATE INDEX IF NOT EXISTS forge_workflow_schema_migrations_lookup_idx ON forge_workflow_schema_migrations(family,state,created_at DESC);
CREATE TABLE IF NOT EXISTS forge_workflow_execution_snapshots (id uuid PRIMARY KEY,tenant_id text NOT NULL,project_id text,episode_id text,plan_id text,family text NOT NULL,version integer NOT NULL CHECK(version>0),schema_hash char(64) NOT NULL,document jsonb NOT NULL,content_hash char(64) NOT NULL,source text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_workflow_execution_snapshots_scope_idx ON forge_workflow_execution_snapshots(tenant_id,project_id,episode_id,created_at DESC);
CREATE INDEX IF NOT EXISTS forge_workflow_execution_snapshots_schema_idx ON forge_workflow_execution_snapshots(family,version,schema_hash);
ALTER TABLE forge_workflow_templates ADD COLUMN IF NOT EXISTS schema_family text NOT NULL DEFAULT 'workflow-definition';
ALTER TABLE forge_workflow_template_versions ADD COLUMN IF NOT EXISTS schema_family text NOT NULL DEFAULT 'workflow-definition';
ALTER TABLE forge_workflow_template_versions ADD COLUMN IF NOT EXISTS schema_version integer NOT NULL DEFAULT 1;
ALTER TABLE forge_workflow_template_versions ADD COLUMN IF NOT EXISTS schema_hash char(64);
ALTER TABLE forge_execution_plans ADD COLUMN IF NOT EXISTS schema_family text NOT NULL DEFAULT 'execution-plan';
ALTER TABLE forge_execution_plans ADD COLUMN IF NOT EXISTS schema_version integer NOT NULL DEFAULT 1;
ALTER TABLE forge_execution_plans ADD COLUMN IF NOT EXISTS schema_hash char(64);
ALTER TABLE forge_execution_plans ADD COLUMN IF NOT EXISTS execution_snapshot_id uuid REFERENCES forge_workflow_execution_snapshots(id) ON DELETE RESTRICT;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS schema_family text NOT NULL DEFAULT 'job-payload';
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS schema_version integer NOT NULL DEFAULT 1;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS schema_hash char(64);
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS schema_snapshot_id uuid REFERENCES forge_workflow_execution_snapshots(id) ON DELETE RESTRICT;
ALTER TABLE forge_execution_runs ADD COLUMN IF NOT EXISTS schema_family text NOT NULL DEFAULT 'runner-manifest';
ALTER TABLE forge_execution_runs ADD COLUMN IF NOT EXISTS schema_version integer NOT NULL DEFAULT 1;
ALTER TABLE forge_execution_runs ADD COLUMN IF NOT EXISTS schema_hash char(64);
ALTER TABLE forge_execution_runs ADD COLUMN IF NOT EXISTS schema_snapshot_id uuid REFERENCES forge_workflow_execution_snapshots(id) ON DELETE RESTRICT;
ALTER TABLE forge_workflow_checkpoints ADD COLUMN IF NOT EXISTS schema_family text NOT NULL DEFAULT 'workflow-checkpoint';
ALTER TABLE forge_workflow_checkpoints ADD COLUMN IF NOT EXISTS schema_hash char(64);
CREATE INDEX IF NOT EXISTS forge_jobs_schema_compat_idx ON forge_jobs(schema_family,schema_version,schema_hash,status);
CREATE INDEX IF NOT EXISTS forge_execution_runs_schema_compat_idx ON forge_execution_runs(schema_family,schema_version,schema_hash,status);
CREATE INDEX IF NOT EXISTS forge_execution_plans_schema_compat_idx ON forge_execution_plans(schema_family,schema_version,schema_hash,status);
COMMIT;